    fun icon(name: String): ImageVector = when (name) {
        "brand" -> brand
        "globe" -> globe
        "lock" -> lock
        "search" -> search
        "plus" -> plus
        "calendar" -> calendar
        "clock" -> clock
        "users" -> users
        "video" -> video
        "videoOff" -> videoOff
        "mic" -> mic
        "micOff" -> micOff
        "screen" -> screen
        "pip" -> pip
        "browser" -> browser
        "folder" -> folder
        "grid" -> grid
        "hand" -> hand
        "more" -> more
        "phone" -> phone
        "chevron" -> chevron
        "back" -> back
        "link" -> link
        "copy" -> copy
        "close" -> close
        "chat" -> chat
        "settings" -> settings
        "pen" -> pen
        "highlighter" -> highlighter
        "eraser" -> eraser
        "undo" -> undo
        "redo" -> redo
        "send" -> send
        "palette" -> palette
        "play" -> play
        "pause" -> pause
        "trash" -> trash
        "alert" -> alert
        "check" -> check
        "speaker" -> speaker
        "cameraFlip" -> cameraFlip
        "wifi" -> wifi
        "file" -> file
        else -> error("Unknown shared icon: $name")
